import re
from datetime import datetime

# Start with input dataframe
df = input_df_1.copy()

# ============================================================================
# STEP 1: DEDUPLICATION
# ============================================================================
# Drop exact duplicates (all columns identical)
df = df.drop_duplicates()

# For remaining rows with same order_id, keep only the first occurrence
df = df.sort_values('order_id', kind='stable').drop_duplicates(subset=['order_id'], keep='first')

# ============================================================================
# STEP 2: CLEAN customer_name
# ============================================================================
def clean_customer_name(val):
    if pd.isna(val):
        return ''
    s = str(val).strip()
    if not s:
        return ''
    # Convert to title case
    return s.title()

df['customer_name'] = df['customer_name'].apply(clean_customer_name)

# ============================================================================
# STEP 3: CLEAN email
# ============================================================================
def clean_email(val):
    if pd.isna(val):
        return ''
    s = str(val).strip().lower()
    if not s:
        return ''
    # Check for invalid markers
    if s in ('n/a', 'none', '-'):
        return ''
    # Check email pattern: must contain @, domain part, and dot-separated TLD, no spaces
    if ' ' in s:
        return ''
    if '@' not in s:
        return ''
    parts = s.split('@')
    if len(parts) != 2:
        return ''
    local_part, domain_part = parts
    if not local_part or not domain_part:
        return ''
    if '.' not in domain_part:
        return ''
    # Simple validation: domain_part should have at least one dot and non-empty before/after
    domain_parts = domain_part.split('.')
    if len(domain_parts) < 2:
        return ''
    for part in domain_parts:
        if not part:
            return ''
    return s

df['email'] = df['email'].apply(clean_email)

# ============================================================================
# STEP 4: CLEAN order_date
# ============================================================================
def clean_order_date(val):
    if pd.isna(val):
        return ''

    # If already a datetime (Timestamp), convert to string for parsing
    if isinstance(val, pd.Timestamp):
        # Check if it's a valid date
        try:
            # If it's a valid Timestamp, format it as YYYY-MM-DD
            dt = val
            if pd.isna(dt):
                return ''
            return dt.strftime('%Y-%m-%d')
        except:
            return ''

    s = str(val).strip()
    if not s:
        return ''

    # Check for invalid unparseable values
    if s.upper() in ('TBD', '00/00/0000', '0000-00-00'):
        return ''

    # Try to parse the date
    dt = None

    # Try ISO format YYYY-MM-DD first
    try:
        dt = pd.to_datetime(s, format='%Y-%m-%d')
        if not pd.isna(dt):
            return dt.strftime('%Y-%m-%d')
    except:
        pass

    # Try slash-separated M/D/Y or MM/DD/YYYY format
    try:
        dt = pd.to_datetime(s, format='%m/%d/%Y')
        if not pd.isna(dt):
            return dt.strftime('%Y-%m-%d')
    except:
        pass

    # Try dash-separated M-D-Y or MM-DD-YYYY format
    try:
        dt = pd.to_datetime(s, format='%m-%d-%Y')
        if not pd.isna(dt):
            return dt.strftime('%Y-%m-%d')
    except:
        pass

    # Try text dates like 'March 8 2026' or '8 March 2026'
    try:
        dt = pd.to_datetime(s)
        if not pd.isna(dt):
            return dt.strftime('%Y-%m-%d')
    except:
        pass

    return ''

df['order_date'] = df['order_date'].apply(clean_order_date)

# ============================================================================
# STEP 5: CLEAN amount_usd
# ============================================================================
def clean_amount_usd(val):
    if pd.isna(val):
        return ''

    s = str(val).strip()
    if not s:
        return ''

    # Remove $, commas, and USD (case-insensitive)
    s = s.replace('$', '').replace(',', '')
    s = re.sub(r'(?i)usd', '', s).strip()

    # Try to parse as number
    try:
        amount = float(s)
        if amount < 0:
            return ''
        return f'{amount:.2f}'
    except:
        return ''

df['amount_usd'] = df['amount_usd'].apply(clean_amount_usd)

# ============================================================================
# STEP 6: CLEAN quantity
# ============================================================================
def clean_quantity(val):
    if pd.isna(val):
        return ''

    s = str(val).strip()
    if not s:
        return ''

    # Mapping of word numbers to integers
    word_to_num = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5,
        'six': 6, 'seven': 7, 'eight': 8, 'nine': 9, 'ten': 10,
        'eleven': 11, 'twelve': 12, 'thirteen': 13, 'fourteen': 14, 'fifteen': 15,
        'sixteen': 16, 'seventeen': 17, 'eighteen': 18, 'nineteen': 19, 'twenty': 20
    }

    s_lower = s.lower()

    # Check if it's a word number
    if s_lower in word_to_num:
        num = word_to_num[s_lower]
        if num <= 0:
            return ''
        return str(num)

    # Try to parse as number
    try:
        # Check if it's a decimal like '2.0'
        val_float = float(s)
        val_int = int(val_float)

        # Check if it's a non-integer decimal (e.g., 1.5)
        if val_float != val_int:
            return ''

        # Check if zero or negative
        if val_int <= 0:
            return ''

        return str(val_int)
    except:
        return ''

df['quantity'] = df['quantity'].apply(clean_quantity)

# ============================================================================
# STEP 7: CLEAN country
# ============================================================================
country_mapping = {
    'au': 'Australia',
    'aus': 'Australia',
    'australia': 'Australia',
    'us': 'United States',
    'usa': 'United States',
    'u.s.': 'United States',
    'u.s.a.': 'United States',
    'united states': 'United States',
    'uk': 'United Kingdom',
    'gb': 'United Kingdom',
    'great britain': 'United Kingdom',
    'united kingdom': 'United Kingdom',
    'nz': 'New Zealand',
    'new zealand': 'New Zealand',
    'in': 'India',
    'india': 'India'
}

def clean_country(val):
    if pd.isna(val):
        return ''

    s = str(val).strip()
    if not s:
        return ''

    # Check mapping (case-insensitive)
    s_lower = s.lower()
    if s_lower in country_mapping:
        return country_mapping[s_lower]

    # Return trimmed original value if not recognized
    return s

df['country'] = df['country'].apply(clean_country)

# ============================================================================
# STEP 8: CLEAN status
# ============================================================================
valid_statuses = {'shipped', 'delivered', 'pending', 'cancelled'}

def clean_status(val):
    if pd.isna(val):
        return ''

    s = str(val).strip().lower()
    if s not in valid_statuses:
        return ''

    return s

df['status'] = df['status'].apply(clean_status)

# ============================================================================
# ENSURE COLUMN ORDER
# ============================================================================
expected_columns = ['order_id', 'customer_name', 'email', 'order_date', 'amount_usd', 'quantity', 'country', 'status']
df = df[expected_columns]

# ============================================================================
# CREATE OUTPUT MASK
# ============================================================================
# Start with the input mask reindexed to match output
output_mask = input_mask_1.reindex(index=df.index, columns=expected_columns, fill_value=False).astype(bool)

# For each cell, mark as True if it was modified
# Compare cleaned values with original
for col in expected_columns:
    if col in input_df_1.columns:
        # Mark cells that differ from original as True (modified)
        # For cells that were originally null/NaN, mark as True if now non-empty
        orig_vals = input_df_1.loc[df.index, col]
        cleaned_vals = df[col]

        # Mark True where value changed
        for idx in df.index:
            orig = orig_vals[idx]
            cleaned = cleaned_vals[idx]

            # Convert both to string for comparison, handling NaN/None
            orig_str = '' if pd.isna(orig) else str(orig).strip()
            cleaned_str = str(cleaned)

            # Special case for order_date: compare as strings since format changed
            if col == 'order_date':
                if isinstance(orig, pd.Timestamp):
                    orig_str = orig.strftime('%Y-%m-%d') if not pd.isna(orig) else ''
                elif pd.isna(orig):
                    orig_str = ''
                else:
                    orig_str = str(orig).strip()

            if orig_str != cleaned_str:
                output_mask.loc[idx, col] = True
            else:
                output_mask.loc[idx, col] = False

output_df = df
